// 已有车种范围不等于具体图库外观授权。以公开入口同时验证 PNG 及 SVG 标记。
test('待审直通车型保持中性标记，不借用其他车型图片',()=>{
 const w={},ctx={window:w,console:{log(){},warn(){},debug(){},error(){}}};
 for(const f of ['data/timetables/vehicle-garage-png-map.js','data/timetables/train-number-png-ranges.js','js/train-vehicle.js'])vm.runInNewContext(fs.readFileSync(f,'utf8'),ctx,{filename:f});
 for(const [base,models] of [[{"positionLineId":"Fukutoshin","sourceRailway":"odpt.Railway:TokyoMetro.Fukutoshin","trainOperator":"TokyoMetro","trainType":"Local","calendarType":"holiday","serviceDate":"2026-11-29","trainNumber":"A1003K","trainOwner":"odpt.TrainOwner:Tokyu","realtimeVehicleType":"東急5050系"},["東急5000系","東急5000系（8両）"]],[{"positionLineId":"Fukutoshin","sourceRailway":"odpt.Railway:TokyoMetro.Fukutoshin","trainOperator":"TokyoMetro","trainType":"Local","calendarType":"holiday","serviceDate":"2026-11-29","trainNumber":"A2211T","trainOwner":"odpt.TrainOwner:Tobu","realtimeVehicleType":"東武9000系"},["東武90000系"]]]){
  const p={...base,displayLineId:base.positionLineId,positionSource:'realtime-api',estimated:false};
  assert.equal(w.TrainVehicle.lookupTrainNumberRangePng(p)?.model,p.realtimeVehicleType);
  assert.equal(w.TrainVehicle.selectMarkerArtwork(p,false).kind,'vehicle');
  for(const model of models){
   const q={...p,realtimeVehicleType:model};
   assert.equal(w.TrainVehicle.lookupTrainNumberRangePng(q),null,model);
   assert.equal(w.TrainVehicle.selectMarkerArtwork(q,false).kind,'unresolved',model);
  }
 }
});
